using System;using System.IO;using System.Collections.Generic;using UnityEngine;using Newtonsoft.Json;
[Serializable] public class FieldItemDefinition {public string name,description,slot,ammo;public float weight,capacity;public int magazine;public bool stack;}
[Serializable] public class FieldItem {public string id,kind,container="carry",attachment="";public int quantity=1,loaded;public float condition=100,contamination,battery=100,filter=100;}
[Serializable] public class FieldDrop {public FieldItem item;public float x,y,z;}
[Serializable] public class FieldSave {public List<FieldDrop> dropped=new List<FieldDrop>();public int schema=1;public int demoAmmoRevision;public List<FieldItem> items=new List<FieldItem>();public HumanCondition health=new HumanCondition();public string equipped="rifle";}
public class WoodlandInventory:MonoBehaviour {
 public TextAsset definitions;public WoodlandPlayer player;public WoodlandAnatomy anatomy;public bool persist=true;
 public FieldSave data=new FieldSave();public Dictionary<string,FieldItemDefinition> defs;public event Action Changed;public string status="";bool ready;float saveClock;
 public string SavePath=>Path.Combine(Application.persistentDataPath,"woodland-field-kit-v1.json");
 public void Initialise(bool load){if(ready)return;defs=JsonConvert.DeserializeObject<Dictionary<string,FieldItemDefinition>>(definitions.text);defs.Remove("smg");defs["suit_patch"]=new FieldItemDefinition{name="Adhesive suit patch",weight=.025f,stack=true,description="Seal a suit breach. Hold P to apply a patch; does not treat wounds."};defs["glowstick"]=new FieldItemDefinition{name="Green glow stick",weight=.035f,stack=true,description="Drop with Y to mark a dark route. Glows for three minutes."};defs["splint"]=new FieldItemDefinition{name="Field splint",weight=.18f,stack=true,description="Stabilises a damaged limb. It does not mend the bone."};if(load&&persist&&File.Exists(SavePath)){try{var saved=JsonConvert.DeserializeObject<FieldSave>(File.ReadAllText(SavePath),new JsonSerializerSettings{ObjectCreationHandling=ObjectCreationHandling.Replace});if(saved==null||saved.schema!=1||saved.items==null||saved.health==null)throw new Exception("Unsupported save");data=saved;data.items.RemoveAll(i=>i==null||!defs.ContainsKey(i.kind)||i.quantity<=0);foreach(var i in data.items){i.quantity=Mathf.Clamp(i.quantity,1,999);i.battery=Mathf.Clamp(i.battery,0,100);i.filter=Mathf.Clamp(i.filter,0,100);}}catch(Exception e){status="Could not load field kit; original save kept. "+e.Message;persist=false;}}
  if(data.items.Count==0){Seed("suit",1);Seed("backpack",1);Seed("rifle",1).loaded=30;Seed("radio",1);Seed("torch",1);Seed("map",1);Seed("notebook",1);Seed("medical",3);Seed("glowstick",6);Seed("filter",2);Seed("torch_cell",3);Seed("556",300);Seed("splint",2);Seed("suit_patch",4);Seed("crowbar",1);Seed("ear_defenders",1);}
  ApplyDemoAmmoTopUp();
  ready=true;if(anatomy)anatomy.condition=data.health;if(player){player.rounds=Find("rifle").loaded;player.battery=Find("torch").battery;}Changed?.Invoke();
 }
 public void ApplyDemoAmmoTopUp(){if(data.demoAmmoRevision>=1)return;int wanted=Mathf.Max(0,300-Count("556"));float weight=defs["556"].weight;int room=weight>0?Mathf.Max(0,Mathf.FloorToInt((Capacity-Weight)/weight)):wanted;int grant=Mathf.Min(wanted,room);if(grant>0)Seed("556",grant);data.demoAmmoRevision=1;}
 void Awake(){Initialise(true);}
 void Start(){if(data.dropped==null)data.dropped=new List<FieldDrop>();foreach(var drop in data.dropped)if(drop.item!=null&&defs.ContainsKey(drop.item.kind))WoodlandLoot.Spawn(drop,defs[drop.item.kind].name);}
 FieldItem Seed(string kind,int count){var i=new FieldItem{id=Guid.NewGuid().ToString("N"),kind=kind,quantity=count};data.items.Add(i);return i;}
 public FieldItem Find(string kind)=>data.items.Find(x=>x.kind==kind&&x.container=="carry");
 public int Count(string kind){int n=0;foreach(var i in data.items)if(i.kind==kind&&i.container=="carry")n+=i.quantity;return n;}
 public float Capacity=>Find("backpack")!=null?24:8;
 public float Weight{get{float total=0;foreach(var i in data.items)if(i.container=="carry"&&defs.ContainsKey(i.kind)){total+=defs[i.kind].weight*i.quantity;if(defs[i.kind].ammo!=null&&defs.ContainsKey(defs[i.kind].ammo))total+=i.loaded*defs[defs[i.kind].ammo].weight;}return total;}}
 public bool Add(string kind,int quantity,float contamination=0){if(!defs.ContainsKey(kind)||quantity<=0||(!defs[kind].stack&&quantity!=1)||Weight+defs[kind].weight*quantity>Capacity)return false;var i=Seed(kind,quantity);i.contamination=Mathf.Clamp(contamination,0,100);Notify("Packed "+defs[kind].name);return true;}
 public bool Consume(string kind,int quantity){if(quantity<=0||Count(kind)<quantity)return false;for(int n=data.items.Count-1;n>=0&&quantity>0;n--){var i=data.items[n];if(i.kind!=kind||i.container!="carry")continue;int take=Mathf.Min(quantity,i.quantity);i.quantity-=take;quantity-=take;if(i.quantity==0)data.items.RemoveAt(n);}Notify("");return true;}
 public int LoadRifle(int wanted){int take=Mathf.Min(wanted,Count("556"));if(take>0)Consume("556",take);return take;}
 public bool Use(string kind){if(Find(kind)==null)return false;switch(kind){case "suit_patch":if(Find("suit")==null||Find("suit").condition>=99){Notify("Suit is sealed.");return false;}Find("suit").condition=100;Consume(kind,1);Notify("Breach sealed. Wounds still need separate treatment.");return true;case "glowstick":return WoodlandGlowstick.Drop(player);case "medical":if(!anatomy||!anatomy.NeedsBandage){Notify("No external bleeding to dress.");return false;}anatomy.Bandage(anatomy.WorstBleed());Consume(kind,1);Notify("Bleeding dressed. Internal injuries still need medical care.");return true;case "splint":foreach(var r in anatomy.condition.regions)if(anatomy.Splint(r.region)){Consume(kind,1);Notify("Limb stabilised. Bone damage remains.");return true;}Notify("No fractured limb needs a splint.");return false;case "filter":if(Find("suit").filter>=99){Notify("Filter is already fresh.");return false;}Consume(kind,1);Find("suit").filter=100;Notify("Fresh filter fitted.");return true;case "torch_cell":if(player.battery>=99){Notify("Torch battery is already full.");return false;}Consume(kind,1);player.battery=100;Find("torch").battery=100;player.TorchCellFitted();Notify("Fresh torch battery fitted.");return true;case "ear_defenders":var e=Find(kind);e.attachment=e.attachment=="ears"?"":"ears";if(player.visorEffects)player.visorEffects.earDefenders=e.attachment=="ears";Notify(e.attachment=="ears"?"Ear defenders on":"Ear defenders removed");return true;default:Notify(defs[kind].description??"Carried supply.");return false;}}
 public void Notify(string text){if(!string.IsNullOrEmpty(text))status=text;Changed?.Invoke();}
 void Update(){if(!ready)return;var suit=Find("suit");if(suit!=null&&anatomy&&!anatomy.Dead){suit.filter=Mathf.Max(0,suit.filter-Time.deltaTime*.025f);if(suit.filter<=0)anatomy.condition.shock=Mathf.Min(100,anatomy.condition.shock+Time.deltaTime*.08f);}saveClock+=Time.unscaledDeltaTime;if(saveClock>10){saveClock=0;Save();}}
 public void Save(){if(!ready||!persist)return;if(player){var gun=Find("rifle");if(gun!=null)gun.loaded=player.rounds;var torch=Find("torch");if(torch!=null)torch.battery=player.battery;}if(anatomy)data.health=anatomy.condition;try{Directory.CreateDirectory(Path.GetDirectoryName(SavePath));string tmp=SavePath+".tmp";File.WriteAllText(tmp,JsonConvert.SerializeObject(data));if(File.Exists(SavePath))File.Replace(tmp,SavePath,SavePath+".bak");else File.Move(tmp,SavePath);}catch(Exception e){status="Field kit save failed: "+e.Message;}}
 void OnApplicationPause(bool paused){if(paused)Save();}void OnApplicationQuit(){Save();}
}
